def solve(n):
    max_sum = 0
    for k in range(1, n):
        for d_L in range(n):
            for d_S in range(d_L):
                max_e_LS = min(k * (n - k), k * d_L, (n - k) * d_S)
                for e_LS in range(max_e_LS, -1, -1):
                    if (k * d_L - e_LS) % 2 == 0 and ((n - k) * d_S - e_LS) % 2 == 0:
                        e_LL = (k * d_L - e_LS) // 2
                        e_SS = ((n - k) * d_S - e_LS) // 2
                        if e_LL >= 0 and e_LL <= k * (k - 1) // 2 and \
                           e_SS >= 0 and e_SS <= (n - k) * (n - k - 1) // 2:
                            max_sum = max(max_sum, e_LS * (d_L - d_S))
                            break
    return max_sum

