import time

def is_graphic_eg(degrees):
    # degrees is already sorted non-increasingly
    n = len(degrees)
    sum_d = sum(degrees)
    if sum_d % 2 != 0:
        return False
    for k in range(1, n + 1):
        left = sum(degrees[:k])
        right = k * (k - 1) + sum(min(k, d) for d in degrees[k:])
        if left > right:
            return False
    return True

def max_weight_subgraph(degrees):
    n = len(degrees)
    # degrees is already sorted non-increasingly
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((degrees[i] - degrees[j], i, j))

    edges.sort(key=lambda x: x[0], reverse=True)

    current_degrees = list(degrees)
    total_w = 0
    for w, i, j in edges:
        if current_degrees[i] > 0 and current_degrees[j] > 0:
            current_degrees[i] -= 1
            current_degrees[j] -= 1
            total_w += w
    return total_w

def solve_all(n):
    max_sum = 0
    def generate(idx, last_val, current_seq):
        nonlocal max_sum
        if idx == n:
            if is_graphic_eg(current_seq):
                max_sum = max(max_sum, max_weight_subgraph(current_seq))
            return

        for d in range(last_val, -1, -1):
            current_seq.append(d)
            generate(idx + 1, d, current_seq)
            current_seq.pop()

    generate(0, n - 1, [])
    return max_sum

