import itertools

def get_max_sum(n):
    max_s = 0
    for edges_tuple in itertools.product([0, 1], repeat=n*(n-1)//2):
        edges = []
        idx = 0
        for i in range(n):
            for j in range(i + 1, n):
                if edges_tuple[idx] == 1:
                    edges.append((i, j))
                idx += 1

        degrees = [0] * n
        for u, v in edges:
            degrees[u] += 1
            degrees[v] += 1

        current_s = 0
        for u, v in edges:
            current_s += abs(degrees[u] - degrees[v])

        if current_s > max_s:
            max_s = current_s
    return max_s

